export enum ANNOTATION_DEFAULTS {
    // Label
    BACKGROUND_COLOR = "#2e2e2e",
    BACKGROUND_OPACITY = 0.4,
    TEXT_COLOR = "#ffffff",
    SUBTITLE_COLOR = "#e6e6e6",
    SUBTITLE_OPACITY = 0.85,
    FONT_SIZE_LINE_ANNOTATION = 15,
    FONT_SIZE_FLOOR_ANNOTATION = 22,
    SUBTITLE_FONT_SIZE = 20,
    BORDER_RADIUS = 8,
    PADDING_X = 10,
    PADDING_Y = 5,
    LINE_SPACING = 4,

    // Connector
    LINE_COLOR = "#000000",
    LINE_OPACITY = 0.8,
    // Height (world Y) the label sits at — "h" in the design sketch.
    LABEL_HEIGHT = 4,
    // Rise/run of the diagonal; higher = steeper, 1 = 45 degrees.
    LINE_SLOPE = 1.2,
    // Length of the flat segment from elbow to label (world units).
    HORIZONTAL_SEGMENT_LENGTH = 1,
    // Alpha at the room end of the diagonal; 0 = fully faded there.
    LINE_FADE_START_ALPHA = 0,

    // Anchor
    ANCHOR_DOT_SIZE = 5,

    // Canvas
    // Supersampling multiplier for crisp text (sprites use sizeAttenuation: false).
    PIXEL_RATIO = 1,
    // Caps PIXEL_RATIO * devicePixelRatio on high-DPI screens.
    MAX_EFFECTIVE_PIXEL_RATIO = 8,

    // Sprite
    SCALE_FACTOR = 0.012,
    // Viewport height SCALE_FACTOR was tuned against; used to normalize sprite size across screens.
    REFERENCE_VIEWPORT_HEIGHT = 900,

    // Tune this once against your scene's units/camera FOV.
    SCREEN_SPACE_SCALE = 0.0015,

    // Tune to taste: bigger number = bigger floor text.
    FLOOR_LABEL_SCALE_PER_RADIUS = 0.002,

    // FLOOR mode: small lift above the floor (fraction of model radius) to avoid z-fighting.
    FLOOR_LABEL_LIFT_PER_RADIUS = 0.0005,

    // higher contrast against the floor texture, e.g. white or black).
    FLOOR_LABEL_TEXT_COLOR = "#000000",

    // 4 / 240 = 1/60. Re-derive the same way if your wall unit changes.
    WALL_HEIGHT_UNIT_SCALE = 4 / 240,

}

/**
 * Display modes for room annotations.
 * - LINE_ANNOTATION: billboarded card with leader lines + anchor dot (original look).
 * - FLOOR_ANNOTATION:   flat text card lying on the floor of the room.
 * - NONE:    no annotations; all label content is removed.
 */
export enum AnnotationMode {
    LINE_ANNOTATION = "line_annotation",
    FLOOR_ANNOTATION = "floor_annotation",
    NONE = "none",
}